<script setup>
import { onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'
const users=ref([]),selected=ref(null),loading=ref(true),error=ref('');onMounted(async()=>{try{const {data,error:e}=await supabase.from('profiles').select('*').order('full_name');if(e)throw e;users.value=data}catch{error.value='Uporabnikov ni bilo mogoče naložiti.'}finally{loading.value=false}})
</script>
<template><section class="page users-page"><header><p class="eyebrow">Sladki kot</p><h1>Uporabniki</h1><p class="muted">Vloge uporabnikov aplikacije</p></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="center-state">Nalagam uporabnike …</div><div v-else class="users-list"><button v-for="user in users" :key="user.id" class="user-row" @click="selected=selected?.id===user.id?null:user"><span class="user-initial">{{(user.full_name||'?').slice(0,1).toUpperCase()}}</span><span class="user-main"><strong>{{user.full_name || 'Brez imena'}}</strong><small>{{user.role === 'admin'?'Administrator':'Popis zaloge'}}</small></span><span class="user-role" :class="user.role">{{user.role==='admin'?'Admin':'Zaposleni'}}</span><span class="user-arrow"><ArrowIcon :direction="selected?.id===user.id?'up':'right'" /></span><span v-if="selected?.id===user.id" class="user-details"><small>UUID uporabnika</small><code>{{user.id}}</code></span></button></div></section></template>
